import {bakeCityFinish} from '../city/surface.js';
import {periodicBuildingNoise,bakeBuildingMaterial} from '../city/building-material.js';
import {bakeSurface,filteredMips} from '../hull/surface.js';
import {encodeMaterialPack} from '../material-production/pack.js';
import {optimizedBuilding} from './model.js';
export const clamp=(x,a=0,b=1)=>Math.max(a,Math.min(b,x)),mix=(a,b,t)=>a+(b-a)*t,linear=c=>c<=.04045?c/12.92:((c+.055)/1.055)**2.4,srgb=c=>c<=.0031308?c*12.92:1.055*c**(1/2.4)-.055,smooth=(a,b,x)=>{const t=clamp((x-a)/(b-a));return t*t*(3-2*t);};
export function maps(size){return{size,color:new Uint8Array(size*size*4),normal:new Uint8Array(size*size*4),surface:new Uint8Array(size*size*4),masks:new Uint8Array(size*size*4)};}
export function uvAt(x,n){const g=n/8,c=n*.75;return(((x-g)%c+c)%c+.5)/c;}
export function normalFromHeight(out,h){const n=out.size,g=n/8,core=n*.75,at=(x,y)=>h[(((y-g)%core+core)%core+g)*n+((x-g)%core+core)%core+g];for(let y=0;y<n;y++)for(let x=0;x<n;x++){const dx=(at(x+1,y)-at(x-1,y))*core/4,dy=(at(x,y+1)-at(x,y-1))*core/4,l=Math.hypot(dx,dy,1),i=(y*n+x)*4;out.normal.set([Math.round((.5-dx/l*.5)*255),Math.round((.5-dy/l*.5)*255),Math.round((.5+.5/l)*255),255],i);}}
export function growthMaps(params,n){const out=maps(n),h=new Float32Array(n*n),noise=periodicBuildingNoise(Number(params.seed??17)>>>0),base=[1,3,5].map(i=>linear(parseInt(params.color.slice(i,i+2),16)/255)),kind={moss:0,lichen:1,snow:2,dust:3}[params.kind]??0;for(let y=0;y<n;y++)for(let x=0;x<n;x++){const u=uvAt(x,n),v=uvAt(y,n),f=noise(u,v,4)*.55+noise(u,v,8)*.28+noise(u,v,16)*.12+noise(u,v,32)*.05,grain=noise(u,v,64),height=([.007,.003,.0003,.0008][kind]*f+[.0015,.0004,.00005,.00012][kind]*grain)*(params.relief??1),i=(y*n+x)*4;h[y*n+x]=height;for(let c=0;c<3;c++)out.color[i+c]=Math.round(clamp(srgb(base[c]*(.7+f*.6+(grain-.5)*.08)))*255);out.color[i+3]=255;out.surface.set([Math.round(clamp(1-(1-grain)*.08)*255),Math.round(clamp(params.roughness+(f-.5)*.12,.12,.98)*255),0,Math.round(clamp(.5+height*40)*255)],i);}normalFromHeight(out,h);return out;}
const maskCache=new WeakMap();
export function maskValue(p,u,v){if(p.coverage<=0)return p.invert?1:0;if(p.coverage>=1)return p.invert?0:1;if(!maskCache.has(p))maskCache.set(p,periodicBuildingNoise(Number(p.seed??17)>>>0));const f=maskCache.get(p)(u,v,Math.max(1,Math.round(p.scale||8))),value=smooth(1-(p.coverage??.5)-(p.softness??.15),1-(p.coverage??.5)+(p.softness??.15),f);return p.invert?1-value:value;}
export function operate(kind,p,a,b,mask){const n=a.size,out=maps(n),noise=periodicBuildingNoise(Number(p.seed??17)>>>0),maskSpec=mask||{seed:p.seed??17,scale:8,coverage:.6,softness:.18},tint=/^#[\da-f]{6}$/i.test(p.tint||'')?[1,3,5].map(i=>linear(parseInt(p.tint.slice(i,i+2),16)/255)):[1,1,1];for(let y=0;y<n;y++)for(let x=0;x<n;x++){const i=(y*n+x)*4,u=uvAt(x,n),v=uvAt(y,n);if(kind==='blend'){let m=mask?maskValue(mask,u,v):p.mode==='uniform'?1:maskValue(maskSpec,u,v);if(p.mode==='cavity')m=clamp((1-a.surface[i]/255)*3+m*.3);if(p.mode==='height'||p.mode==='upward')m*=smooth(.15,.85,v);let w=clamp((p.amount??.6)*m);w=clamp(w+(b.surface[i+3]-a.surface[i+3])/255*(p.heightBlend||0)*4*w*(1-w));for(let c=0;c<3;c++)out.color[i+c]=Math.round(clamp(srgb(mix(linear(a.color[i+c]/255),linear(b.color[i+c]/255),w)))*255);out.color[i+3]=255;const normal=[0,1,2].map(c=>mix(a.normal[i+c]/127.5-1,b.normal[i+c]/127.5-1,w)),l=Math.hypot(...normal)||1;for(let c=0;c<3;c++)out.normal[i+c]=Math.round((normal[c]/l*.5+.5)*255);out.normal[i+3]=255;for(let c=0;c<4;c++)out.surface[i+c]=Math.round(c===1?Math.sqrt(mix((a.surface[i+c]/255)**2,(b.surface[i+c]/255)**2,w))*255:mix(a.surface[i+c],b.surface[i+c],w));}
 else{out.color.set(a.color.subarray(i,i+4),i);out.normal.set(a.normal.subarray(i,i+4),i);out.surface.set(a.surface.subarray(i,i+4),i);if(kind==='finish'){for(let c=0;c<3;c++)out.color[i+c]=Math.round(clamp(srgb(linear(a.color[i+c]/255)*tint[c]))*255);out.surface[i+1]=Math.round(clamp(a.surface[i+1]/255*(p.roughness??1),.04,.98)*255);const nn=[(a.normal[i]/127.5-1)*(p.normalStrength??1),(a.normal[i+1]/127.5-1)*(p.normalStrength??1),a.normal[i+2]/127.5-1],l=Math.hypot(...nn)||1;for(let c=0;c<3;c++)out.normal[i+c]=Math.round((nn[c]/l*.5+.5)*255);}else{const f=noise(u,v,8),dirt=clamp((p.grime??.35)*(f*.3+(1-smooth(.005,.04,Math.min(u,1-u,v,1-v)))*.6)),wet=(p.wetness||0)*f;for(let c=0;c<3;c++)out.color[i+c]=Math.round(clamp(srgb(linear(a.color[i+c]/255)*(1-dirt*.5)*(1-wet*.2)))*255);out.surface[i+1]=Math.round(clamp(a.surface[i+1]/255+dirt*.15-wet*.25,.12,.98)*255);out.surface[i+2]=Math.round(a.surface[i+2]*(1-dirt));}}
 }return out;}
export function hullMaps(params,n,bitmaps){const source=bakeSurface({...params.recipe,tileMeters:2},n,bitmaps),out=maps(n);for(let y=0;y<n;y++)for(let x=0;x<n;x++){const sx=Math.min(n-1,Math.floor(uvAt(x,n)*n)),sy=Math.min(n-1,Math.floor(uvAt(y,n)*n)),a=(sy*n+sx)*4,b=(y*n+x)*4;out.color.set(source.color.subarray(a,a+4),b);out.normal.set(source.normal.subarray(a,a+4),b);out.surface.set(source.surface.subarray(a,a+4),b);out.surface[b+3]=Math.round(clamp(.5+(source.surface[a+3]/255-.5)*.028*40)*255);}return out;}
export function packMaps(out,graph,producer='graph-cpu'){const levels=filteredMips(out).filter(l=>l.width>=8);return encodeMaterialPack({recipe:graph,levels,producer,atlas:{columns:1,rows:1,guardFraction:.125}});}
export async function executeCPU(program,n,load){const cache=new Map();async function visit(node){if(cache.has(node.id))return cache.get(node.id);const specialized=optimizedBuilding({root:node});let out;if(specialized)out=bakeBuildingMaterial(specialized.recipe,specialized.zone,n);else if(node.kind==='urban')out=bakeCityFinish(node.params,n);else if(node.kind==='hull')out=hullMaps(node.params,n,await load?.('images',node.params));else if(node.kind==='growth')out=growthMaps(node.params,n);else if(node.kind==='bitmap'||node.kind==='scan'||node.kind==='pack'||node.kind==='localPack')out=await load(node.kind,node.params,n);else if(node.kind==='noise')out=node.params;else{const a=await visit(node.inputs[node.kind==='blend'?'base':'in']);out=operate(node.kind,node.params,a,node.inputs.layer?await visit(node.inputs.layer):null,node.inputs.mask?await visit(node.inputs.mask):null);}cache.set(node.id,out);return out;}return visit(program.root);}
